"""Offline, escaped inspection artifact. No scripts, network calls or tracking."""
import html,json

def render(report):
    escape=lambda value:html.escape(str(value),quote=True)
    def plan_card(title,plan):
        pairs=''.join('<li><strong>'+escape(job)+'</strong> &rarr; '+escape(resource)+'</li>' for job,resource in plan['assignments'].items()) or '<li>No assignments</li>'
        return '<section><h2>'+title+'</h2><ul>'+pairs+'</ul><p>Covered priority: '+str(plan['covered_priority'])+'<br>Travel cost: '+str(plan['travel_cost'])+'</p><p>Unassigned: '+escape(', '.join(plan['unassigned']) or 'none')+'</p></section>'
    rows=''.join('<tr><td>'+escape(item['key'])+'</td><td>'+escape((item['before'] or {}).get('event_id','absent'))+'</td><td>'+escape((item['after'] or {}).get('event_id','absent'))+'</td></tr>' for item in report['witness'])
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AfterFact decision replay</title><style>
    :root{color-scheme:dark}*{box-sizing:border-box}body{background:#111110;color:#e5e4dd;font:16px/1.7 system-ui,sans-serif;max-width:980px;margin:auto;padding:42px 22px}h1,h2,th{font-family:ui-monospace,monospace}h1{font-size:32px}h2{font-size:18px}a{color:#b5c6a8}.muted{color:#aaa99f}.plans{display:grid;grid-template-columns:1fr 1fr;gap:20px}section{border:1px solid #393934;padding:20px}table{border-collapse:collapse;width:100%}th,td{text-align:left;border-bottom:1px solid #393934;padding:12px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;padding:18px;background:#191918}details{margin-top:28px}@media(max-width:620px){.plans{grid-template-columns:1fr}th,td{padding:8px;font-size:12px}}
    </style></head><body><p class="muted">AF / TWO CLOCKS, ONE DECISION</p><h1>What changed after the fact?</h1><p>''' + escape(report['input_provenance']) + '''</p><p>Effective cutoff: <strong>''' + str(report['valid_at']) + '</strong>. Knowledge changed from <strong>' + str(report['known_before']) + '</strong> to <strong>' + str(report['known_after']) + '''</strong>.</p><div class="plans">''' + plan_card('What we knew then',report['before']) + plan_card('With the corrections',report['after']) + '''</div><h2>The small explanation</h2><p>''' + str(len(report['changed_facts'])) + ' facts changed. ' + str(len(report['witness'])) + ''' retained corrections reproduce the new result. Removing any single retained correction breaks that reproduction.</p><table><thead><tr><th>Fact</th><th>Earlier source</th><th>Later source</th></tr></thead><tbody>''' + rows + '''</tbody></table><p class="muted">This is a deletion-1-minimal explanation inside this assignment model, not proof of real-world causality or the smallest possible explanation. Priorities, travel costs and deadlines are inputs. This tool does not dispatch people or calculate routes.</p><details><summary>Inspect the replay and source records</summary><pre>''' + escape(json.dumps(report,indent=2)) + '''</pre></details><p><a href="https://github.com/abhikhur27/portfolio-utility-suite/tree/main/tools/afterfact">Code, input format and reproduction</a></p></body></html>'''
